 const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
