 const api=async(path,method='GET',body)=>{const r=await fetch('/api/staff/work'+path,{method,cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>({}));if(r.status===401){location.href='/login.html?returnTo='+encodeURIComponent(location.pathname+location.search+location.hash);throw Error('Vui lòng đăng nhập lại.');}if(!r.ok)throw Error(data.error||'Không thực hiện được. Vui lòng thử lại.');return data;};
 const saveQuoteCare=async(id,body)=>{const r=await fetch('/api/staff/quotes/'+encodeURIComponent(id)+'/care',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json().catch(()=>({}));if(r.status===401){location.href='/login.html?returnTo='+encodeURIComponent(location.pathname+location.search+location.hash);throw Error('Vui lòng đăng nhập lại.');}if(!r.ok)throw Error(data.error||'Không lưu được lịch chăm sóc.');return data;};
