 function setupSelector(){const prior=$('#wr-branch').value;$('#wr-branch').innerHTML=context.branches.map(b=>`<option value="${safe(b.id)}">${safe(b.name)}</option>`).join('');if(context.branches.some(b=>b.id===prior))$('#wr-branch').value=prior;$('#wr-selector').hidden=!context.branches.length||!['start','end'].includes(tab);$('#wr-settings-tab').hidden=context.user.role!=='manager';setupShiftPresets();}
 let identityChecked=false;async function loadContext(){context=await api('/context');if(context.user.role==='manager'&&!identityChecked){const r=await fetch('/api/staff/admin/reconcile-staff',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('Chưa kiểm tra được hồ sơ nhân viên trùng. Vui lòng thử lại.');const result=await r.json();identityChecked=true;if(result.merged?.length){context=await api('/context');message('Đã hợp nhất '+result.merged.length+' hồ sơ nhân viên trùng, giữ nguyên đăng nhập và chức vụ trên web.');}if(result.review?.length)message(result.review.length+' hồ sơ cần kiểm tra lịch sử hoặc thông tin trước khi hợp nhất.',true);}$('#wr-user').textContent=context.user.name+' · '+(context.user.position||context.user.role);setupSelector();}
