 const quickTaskCards=(tasks=[])=>{const selected=new Set(tasks.map(task=>task.title));const groups=[['Mở ca','Không gian và thiết bị',[['Mở cửa, vệ sinh'],['Kiểm tra POS/QR']]],['Đơn và khách','Chủ động doanh số',[['Gọi khách hẹn'],['Cập nhật đơn Sapo']]],['Quỹ và bàn giao','Đầu ca chắc số liệu',[['Đối chiếu quỹ'],['Đọc bàn giao']]]];return `<div class="wr-quick-grid">${groups.map(([title,caption,items])=>`<section class="wr-quick-card"><div><b>${safe(title)}</b><small>${safe(caption)}</small></div>${items.map(([task])=>`<button type="button" data-quick-task="${safe(task)}" class="${selected.has(task)?'is-selected':''}"><i aria-hidden="true">${selected.has(task)?'✓':'+'}</i><span>${safe(task)}</span></button>`).join('')}</section>`).join('')}</div>`;};
